import{_ as a,o,c as t,a2 as s}from"./chunks/framework.DuIuz2Sv.js";const h=JSON.parse('{"title":"Cenários","description":"","frontmatter":{},"headers":[],"relativePath":"reference/scenarios.md","filePath":"reference/scenarios.md","lastUpdated":1781623519000}'),i={name:"reference/scenarios.md"};function r(n,e,d,u,l,c){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="cenarios" tabindex="-1">Cenários <a class="header-anchor" href="#cenarios" aria-label="Permalink to &quot;Cenários&quot;">​</a></h1><p>Casos reais e o fluxo recomendado para cada um.</p><h2 id="comecei-um-projeto-do-zero" tabindex="-1">&quot;Comecei um projeto do zero&quot; <a class="header-anchor" href="#comecei-um-projeto-do-zero" aria-label="Permalink to &quot;&quot;Comecei um projeto do zero&quot;&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sl.init → /sl.new → /sl.plan → /sl.build → /sl.review → /sl.done</span></span></code></pre></div><p>Faça o onboarding uma vez (<code>sl.init</code>); depois cada feature segue o fluxo padrão.</p><h2 id="tenho-um-codebase-legado-e-nao-sei-a-arquitetura" tabindex="-1">&quot;Tenho um codebase legado e não sei a arquitetura&quot; <a class="header-anchor" href="#tenho-um-codebase-legado-e-nao-sei-a-arquitetura" aria-label="Permalink to &quot;&quot;Tenho um codebase legado e não sei a arquitetura&quot;&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sl.xray → /sl.audit</span></span></code></pre></div><p><code>xray</code> mapeia a arquitetura e gera padrões do projeto; <code>audit</code> aponta dívidas e riscos. Depois siga com <code>/sl.new</code> para novas features — o método já conhece o terreno.</p><h2 id="preciso-adicionar-uma-feature-bem-definida" tabindex="-1">&quot;Preciso adicionar uma feature bem definida&quot; <a class="header-anchor" href="#preciso-adicionar-uma-feature-bem-definida" aria-label="Permalink to &quot;&quot;Preciso adicionar uma feature bem definida&quot;&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sl.new → /sl.plan → /sl.build → /sl.review → /sl.done</span></span></code></pre></div><p>O fluxo Padrão. <code>sl.new</code> fixa os requisitos antes de codar.</p><h2 id="bug-critico-em-producao-agora" tabindex="-1">&quot;Bug crítico em produção, agora&quot; <a class="header-anchor" href="#bug-critico-em-producao-agora" aria-label="Permalink to &quot;&quot;Bug crítico em produção, agora&quot;&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sl.diagnose → /sl.hotfix → /sl.done</span></span></code></pre></div><p><code>diagnose</code> confirma que é hotfix (e não uma feature disfarçada); <code>hotfix</code> corrige rápido.</p><h2 id="quero-que-a-ia-toque-sozinha" tabindex="-1">&quot;Quero que a IA toque sozinha&quot; <a class="header-anchor" href="#quero-que-a-ia-toque-sozinha" aria-label="Permalink to &quot;&quot;Quero que a IA toque sozinha&quot;&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sl.autopilot</span></span></code></pre></div><p>Para escopo já claro. Ele roda plan → build → review e te entrega o resultado.</p><h2 id="a-tela-ta-feia-quero-padronizar-o-visual" tabindex="-1">&quot;A tela tá feia / quero padronizar o visual&quot; <a class="header-anchor" href="#a-tela-ta-feia-quero-padronizar-o-visual" aria-label="Permalink to &quot;&quot;A tela tá feia / quero padronizar o visual&quot;&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sl.design   (ou /sl.ux para ajustes pontuais)</span></span></code></pre></div><p>A skill <code>sl-ux-design</code> traz metodologia (Leis de UX, DQS, padrões SaaS) <strong>e</strong> tokens de marca via <code>DESIGN.md</code> — dá pra pedir &quot;com a cara da Linear/Stripe&quot;.</p><h2 id="vou-abrir-um-pr" tabindex="-1">&quot;Vou abrir um PR&quot; <a class="header-anchor" href="#vou-abrir-um-pr" aria-label="Permalink to &quot;&quot;Vou abrir um PR&quot;&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sl.pull-request</span></span></code></pre></div><p>Idempotente: cria o PR ou atualiza o existente, gerando o changelog da feature.</p><h2 id="quero-subir-a-cobertura-de-testes" tabindex="-1">&quot;Quero subir a cobertura de testes&quot; <a class="header-anchor" href="#quero-subir-a-cobertura-de-testes" aria-label="Permalink to &quot;&quot;Quero subir a cobertura de testes&quot;&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sl.test</span></span></code></pre></div><p>Detecta o framework de testes e gera em paralelo por área, mirando ~80%.</p>',26)])])}const b=a(i,[["render",r]]);export{h as __pageData,b as default};
